import json, numpy as np
P = practice(); lab = {l:i for i,l in enumerate(LABELS)}
y = np.array([lab[p['label']] for p in P])
m1 = json.load(open('pass_1/meta.json')); print({k:(v if not isinstance(v,list) else v[:2]) for k,v in m1.items()})
def load(name):
    return np.concatenate([np.load(f'pass_1/{name}.npy'), np.load(f'pass_2/{name}.npy')])
feats = {}
for L in range(13):
    feats[f'cls{L}'] = load(f'cls_hidden_L{L}'); feats[f'mean{L}'] = load(f'mean_hidden_L{L}')
feats['pooled'] = load('pooled')
np.savez_compressed('base_feats.npz', y=y, **feats)
rng = np.random.default_rng(0); folds = np.zeros(len(y),int)
for c in range(8):
    idx = np.where(y==c)[0]; rng.shuffle(idx); folds[idx] = np.arange(len(idx))%5
np.save('folds.npy', folds)
def lda_fit(X, y, alpha):
    mu = X.mean(0); Xc = X - mu
    means = np.stack([Xc[y==c].mean(0) for c in range(8)])
    R = Xc - means[y]
    S = R.T@R/len(y)
    S = (1-alpha)*S + alpha*np.trace(S)/S.shape[0]*np.eye(S.shape[0])
    Wt = np.linalg.solve(S, means.T).T
    b = -0.5*np.sum(Wt*means,1) - Wt@mu
    return Wt, b
def ridge_fit(X,y,lam):
    mu=X.mean(0); sd=X.std(0)+1e-6; Z=(X-mu)/sd
    T=np.eye(8)[y]-1/8
    A=np.linalg.solve(Z.T@Z+lam*np.eye(Z.shape[1]), Z.T@T)
    Wt=(A/sd[:,None]).T; b=T.mean(0)+1/8 - Wt@mu
    return Wt,b
def cv(X, fit, p):
    pred=np.zeros(len(y),int)
    for f in range(5):
        tr=folds!=f; Wt,b=fit(X[tr],y[tr],p); pred[~tr]=np.argmax(X[~tr]@Wt.T+b,1)
    return (pred==y).mean()
for k in [f'{t}{L}' for L in range(13) for t in ['cls','mean']]+['pooled']:
    X=feats[k].astype(np.float64)
    r=[cv(X,lda_fit,a) for a in [0.1,0.3,0.6]]
    print(k, ' '.join(f'{v:.3f}' for v in r))
